func (w *gzipResponseWriter) Write(b []byte) (int, error) {
	if len(b) == 0 {
		// Nothing to compress: do not write the gzip header (which would
		// otherwise end up in the response body while the Content-Encoding
		// header is removed for empty responses).
		return 0, nil
	}
	if w.Header().Get(echo.HeaderContentType) == "" {
		w.Header().Set(echo.HeaderContentType, http.DetectContentType(b))
	}
	return w.Writer.Write(b)
}

